package com.nulljosh.nimble

/**
 * BC Social Studies 10 with no network, Canada and the World 1914 to the present: government and elections, the
 * Constitution and the Charter, autonomy, discriminatory policies, Indigenous peoples and reconciliation, the world
 * wars, the Depression, the Cold War, Quebec and the political spectrum. A port of `ss10()` in docs/engine.js; the
 * tables are copied from there by script.
 */
internal object SocialStudies10 {
    /** Phrase questions, matched anywhere. */
    private val facts = listOf(
        """\b(?:three |3 )?(?:levels|orders) of government\b""" to "Federal (Parliament in Ottawa and the prime minister), provincial or territorial (for BC, the legislature in Victoria and the premier), and municipal or local (city councils, mayors and regional districts). First Nations governments are a further order of government.",
        """\b(?:three |3 )?branches of (?:the )?government\b""" to "Executive (the Crown, the prime minister and cabinet, who carry out laws), legislative (Parliament: the House of Commons and the Senate, which make laws) and judicial (the courts, which interpret laws).",
        """^(?=.*\b(?:canad|bc\b|british columbia)).*\bhead of state\b""" to "The monarch, King Charles III, represented in Canada by the governor general and in each province by a lieutenant governor. The prime minister is the head of government.",
        """^(?!.*\b(?:uk|britain|british|england|united kingdom)\b).*(?:\bhow many (?:seats|mps|members(?: of parliament)?)\b.*\b(?:house of commons|parliament of canada|canada)\b|\bnumber of seats\b.*\bhouse of commons\b)""" to "343, one for each riding, since the 2025 election (up from 338).",
        """^(?=.*\b(?:canad|bc\b|british columbia)).*\b(?:electoral|voting) system\b""" to "First past the post (single-member plurality): each riding elects one member, and the candidate with the most votes wins, even without a majority.",
        """\bconstitution\b.*\bpatriat|\bpatriat\w*\b.*\bconstitution\b""" to "1982. The Constitution Act, 1982 brought the constitution home from Britain and added the Charter of Rights and Freedoms. Queen Elizabeth II proclaimed it in Ottawa on April 17, 1982.",
        """\bjapanese canadians?\b""" to "After Pearl Harbor in 1941, about 22,000 Japanese Canadians, most of them Canadian citizens, were forced from the BC coast and interned in camps in the interior, and their homes, boats and businesses were seized and sold. Canada apologized and paid redress in 1988.",
        """\blast residential school\b|\bresidential schools?\b.*\b(?:close|closed|closing|end|ended)\b""" to "1996: Gordon's Indian Residential School in Saskatchewan was the last federally run one to close. About 150,000 First Nations, Métis and Inuit children attended residential schools from the 1880s on.",
        """\bcaused? (?:of )?the (?:great )?depression\b|\bcauses of the (?:great )?depression\b""" to "The stock market crash of October 1929, overproduction and buying on credit, falling wheat prices and drought on the Prairies, high tariffs that choked world trade (like the American Smoot-Hawley tariff), and Canada's heavy dependence on exports of raw materials.",
        """^(?=.*\b(?:canad|bc\b|british columbia)).*(?:\bwomen\b.*\b(?:vote|voting|suffrage)\b|\b(?:vote|suffrage)\b.*\bwomen\b)""" to "Most women won the federal vote in 1918 (nurses serving overseas and soldiers' female relatives in 1917). Manitoba was first provincially, in 1916, and BC followed in 1917. Asian Canadians won the vote in 1947 to 1949, and First Nations people without giving up status in 1960.",
        """\bcanada\b.*\bdeclared? war\b|\bdeclared? war\b.*\bcanada\b""" to "On September 10, 1939, a week after Britain, by its own vote in Parliament, a sign of its independence after the Statute of Westminster. In 1914 Canada was at war automatically when Britain declared war.",
        """\bquebec\b.*\breferend|\breferend\w*\b.*\bquebec\b""" to "Quebec held two sovereignty referendums: in 1980, 59.6 percent voted No; in 1995 the No side won by a hair, 50.6 percent to 49.4.",
        """\bwho\b.*\bmulticulturalism\b|\b(?:official )?multiculturalism (?:policy|act)\b|\bofficial multiculturalism\b""" to "Prime Minister Pierre Elliott Trudeau announced official multiculturalism in 1971, a world first, and Brian Mulroney's government passed the Canadian Multiculturalism Act in 1988.",
        """\bfather of medicare\b|\bwho (?:created|started|introduced|brought in)\b.*\b(?:medicare|universal health care|public health care)\b""" to "Tommy Douglas, premier of Saskatchewan, whose government brought in public medical insurance there in 1962; it went national under Lester Pearson in 1966. In 2004 Canadians voted him the Greatest Canadian.",
        """\bwhat (?:does|do) (?:the )?federal government\b|\bfederal (?:responsibilities|powers|jurisdiction)\b""" to "National matters: defence and the military, foreign affairs, currency and banking, criminal law, citizenship and immigration, Indigenous relations, the post office, fisheries and the census.",
        """\bwhat (?:does|do) (?:the |a )?provincial governments?\b|\bprovincial (?:responsibilities|powers|jurisdiction)\b""" to "Education, health care and hospitals, highways, natural resources, property and civil rights, driver's licences, and the municipalities themselves.",
        """\bwhat (?:does|do) (?:the |a )?(?:municipal|local|city) governments?\b|\b(?:municipal|local) (?:government )?(?:responsibilities|powers)\b""" to "Local services: garbage and recycling, water and sewers, local roads and transit, police and fire protection, parks, libraries, and zoning and building permits.",
        """\bhead of (?:the )?government\b""" to "The prime minister, the leader of the party that holds the confidence of the House of Commons. In a province, it is the premier. The King is the head of state.",
        """\bhow (?:is|are) (?:the |a )?prime ministers? (?:chosen|selected|elected|picked)\b|\bhow (?:do|does) (?:you|someone|canada|canadians) (?:become|choose|pick|elect) (?:the |a )?prime minister\b""" to "Canadians do not vote for the prime minister directly. They elect an MP in each riding; the leader of the party that wins the most seats, and can keep the confidence of the House of Commons, is asked by the governor general to form a government and becomes prime minister.",
        """\bhow (?:does|do|is) (?:a )?bills? (?:become|made into|passed into) (?:a )?laws?\b|\bhow (?:are|is) (?:a )?laws? (?:made|passed)\b""" to "A bill gets first reading (introduced), second reading (debated in principle), committee study, report stage and third reading in the House of Commons, then the same steps in the Senate, then royal assent from the governor general, when it becomes law.",
        """\bhow many (?:judges|justices)\b.*\bsupreme court\b""" to "Nine: the chief justice and eight other justices, three of whom must come from Quebec. They serve until age 75.",
        """\brights\b.*\bcharter\b.*\b(?:protect|guarantee|include)|\bcharter\b.*\b(?:protects?|guarantees?)\b""" to "Fundamental freedoms (conscience and religion, thought and expression, peaceful assembly, association), democratic rights (to vote and run for office), mobility rights, legal rights (life, liberty, a fair trial), equality rights, and official language and minority language education rights.",
        """\bstatute of westminster\b""" to "1931. The British law made Canada and the other dominions equal to Britain and independent in making their own laws and foreign policy. Amending the constitution still needed Britain until 1982.",
        """\bflag\b.*\b(?:adopted|introduced|created|chosen|raised)\b|\bwhen\b.*\b(?:maple leaf|canad\w*) flag\b""" to "February 15, 1965, under Lester Pearson, after the Great Flag Debate of 1964. It replaced the Red Ensign.",
        """\bjuno beach\b""" to "On D-Day, June 6, 1944, about 14,000 Canadian troops landed at Juno Beach in Normandy, one of five Allied beaches, and pushed farther inland than any other Allied force that day; 359 were killed.",
        """\blester (?:b\.? )?pearson\b""" to "Canada's 14th prime minister (1963 to 1968). As foreign minister he won the 1957 Nobel Peace Prize for proposing the first UN peacekeeping force, in the Suez Crisis. His government brought in the maple leaf flag, national medicare and the Canada Pension Plan.",
        """^(?=.*\b(?:canad|bc\b|british columbia)).*\bprime minister\b.*\b(?:world war (?:ii|2|two)|second world war|ww ?2|wwii)\b""" to "William Lyon Mackenzie King, prime minister from 1935 to 1948 (and 1921 to 1930), Canada's longest-serving prime minister.",
        """^(?=.*\b(?:canad|bc\b|british columbia)).*\bprime minister\b.*\b(?:world war (?:i|1|one)|first world war|ww ?1|wwi)\b""" to "Sir Robert Borden, prime minister from 1911 to 1920.",
        """^(?!.*\b(?:us|usa|united states|america|american|uk|britain|british|england|australia|india|france|germany|mexico)\b).*(?:\bhow (?:long|often)\b.*\belections?\b|\bmaximum (?:term|length)\b.*\b(?:government|parliament)\b)""" to "Five years at most, under section 4 of the Charter, except in war or emergency with two-thirds support. Fixed-date laws set federal and BC elections every four years, but a government can fall or call one sooner.",
        """^(?=.*\b(?:canad|bc\b|british columbia)).*(?:\bvoting age\b|\bage (?:to|you can|can you) vote\b|\bhow old\b.*\bvote\b)""" to "18, in federal elections and in every province and territory. Voters must also be Canadian citizens.",
        """\b(?:first nations|status indians?|indigenous peoples?|aboriginal peoples?)\b.*\b(?:vote|voting|franchise)\b""" to "1960, under John Diefenbaker: First Nations people won the federal vote without having to give up their status. Inuit had won it in 1950.",
        """\b(?:who|what) (?:are|were|is) (?:the )?m[eé]tis\b""" to "One of the three Aboriginal peoples named in the Constitution: a distinct nation descended from First Nations women and European, mostly French and Scottish, fur traders, centred on the Red River and the Prairies, with their own language, Michif. Louis Riel led them in 1869 to 1870 and in 1885.",
        """\blouis riel\b""" to "The Métis leader of the Red River Resistance of 1869 to 1870, which brought Manitoba into Confederation, and of the North-West Resistance of 1885 in Saskatchewan. He was hanged for treason in Regina in 1885 and is now honoured as a founder of Manitoba.",
        """\bren[eé] l[eé]vesque\b""" to "The founder of the Parti Québécois and premier of Quebec from 1976 to 1985. He led the Yes side in the 1980 sovereignty referendum, and his government passed Bill 101.",
    ).map { Regex(it.first) to it.second }

    /** Institutions, events and ideas, matched as the whole term by Terms. */
    private val terms = listOf(
        """ridings?|electoral districts?|constituenc(?:y|ies)""" to "An electoral district (constituency): the area whose voters elect one member of Parliament or of the legislature. Canada has 343 federal ridings; BC has 93 provincial ones.",
        """(?:the )?official opposition""" to "The party with the second most seats. It questions and criticizes the government, above all in Question Period, proposes alternatives and holds the government accountable, ready to govern itself.",
        """responsible government""" to "Government in which the cabinet must keep the confidence (majority support) of the elected assembly or else resign or call an election, so it stays accountable to the people's representatives. Nova Scotia won it first, in 1848.",
        """majority governments?""" to "A government whose party holds more than half the seats (172 of 343 in the House of Commons), so it can pass bills on its own votes.",
        """proportional representation""" to "An electoral system where each party's share of seats matches its share of the vote. BC voted on changing to a form of it in 2005, 2009 and 2018 and kept first past the post each time.",
        """(?:the )?supreme court of canada""" to "Canada's highest court and final court of appeal, in Ottawa: nine judges who decide constitutional and Charter cases and the most important legal questions. Its rulings bind every other court.",
        """section 35(?: of the constitution act,? 1982)?""" to "The section of the Constitution Act, 1982 that recognizes and affirms the existing Aboriginal and treaty rights of the Aboriginal peoples of Canada: First Nations, Inuit and Métis.",
        """(?:the )?winnipeg general strike""" to "From May 15 to June 25, 1919, about 30,000 workers in Winnipeg walked off the job for better wages and the right to collective bargaining. On Bloody Saturday, June 21, the RCMP charged a crowd and two strikers were killed.",
        """(?:the )?chinese exclusion act|(?:the )?chinese immigration act(?:,? 1923)?""" to "The Chinese Immigration Act of 1923, which banned almost all Chinese immigration to Canada from July 1, 1923, a day Chinese Canadians called Humiliation Day, until it was repealed in 1947.",
        """(?:the )?sixties scoop""" to "From the 1950s to the 1980s, child welfare agencies took about 20,000 First Nations, Métis and Inuit children from their families and placed them for adoption or in foster care, mostly with non-Indigenous families, cutting them off from their cultures.",
        """(?:the )?war measures act""" to "A 1914 federal law that gave cabinet sweeping emergency powers, overriding civil liberties. It was used in both world wars (to intern Ukrainian and Japanese Canadians) and in the 1970 October Crisis, and was replaced by the Emergencies Act in 1988.",
        """(?:the )?(?:battle of )?passchendaele""" to "A First World War battle in the mud of Belgium in October and November 1917. Canadian troops took the village of Passchendaele on November 6 at a cost of about 16,000 casualties, more than 4,000 of them killed.",
        """(?:the )?dieppe raid|(?:the )?raid on dieppe""" to "A failed Allied raid on the German-held port of Dieppe, France, on August 19, 1942. Of about 5,000 Canadians, 916 were killed and nearly 2,000 captured. Its lessons helped plan D-Day.",
        """(?:the )?avro arrow|(?:the )?avro cf-105(?: arrow)?|(?:the )?cf-105(?: arrow)?""" to "The Avro CF-105 Arrow, a supersonic interceptor jet built by Avro Canada that first flew in 1958. Prime Minister John Diefenbaker cancelled it on February 20, 1959, and about 30,000 jobs were lost.",
        """peacekeeping""" to "Using neutral, lightly armed forces, usually under the United Nations, to keep the peace between sides in a conflict, watch ceasefires and protect civilians. Lester Pearson proposed the first UN force in 1956.",
        """bill 101|(?:the )?charter of the french language""" to "Quebec's Charter of the French Language, passed in 1977 by René Lévesque's Parti Québécois. It made French the official language of Quebec, of work and of signs, and sent most immigrant children to French schools.",
        """(?:the )?official languages act""" to "The 1969 federal law, under Pierre Trudeau, that made English and French equal official languages of the government of Canada, so federal services are offered in both.",
        """(?:the )?oka crisis""" to "A 78-day standoff in 1990 between Mohawk protesters of Kanesatake and Quebec police, then the Canadian army, over a plan to expand a golf course onto pines and a burial ground at Oka. A police officer was killed.",
        """(?:the )?nisga'?a (?:final agreement|treaty)""" to "The first modern treaty in BC, signed in 1998 and in effect in 2000. It gave the Nisga'a Nation about 2,000 square kilometres of the Nass Valley and self-government.",
        """(?:the )?calder (?:case|decision)|calder v\.? (?:british columbia|bc)""" to "A 1973 Supreme Court of Canada case brought by Frank Calder and the Nisga'a. The court agreed that Aboriginal title existed in law before colonization, which led Canada to start negotiating land claims.",
        """(?:the )?delgamuukw(?: decision| case| v\.? british columbia)?""" to "A 1997 Supreme Court of Canada ruling in a case brought by Gitxsan and Wet'suwet'en hereditary chiefs. It held that Aboriginal title is a right to the land itself and that oral histories count as evidence.",
        """right[- ]wing(?: ideology| politics)?|(?:the )?political right""" to "The side of the political spectrum that favours tradition, individual freedom and a free market, with less government, lower taxes and fewer regulations. In Canada the Conservative Party sits on the right.",
        """nafta|(?:the )?north american free trade agreement""" to "The North American Free Trade Agreement among Canada, the United States and Mexico, in force from 1994. It was replaced by CUSMA (the USMCA) in 2020.",
        """(?:the )?great depression""" to "The worldwide economic collapse from the stock market crash of 1929 through the 1930s. In Canada close to 30 percent of workers were unemployed by 1933, and the Prairies were hit hardest by drought and falling wheat prices (the Dirty Thirties).",
        """(?:the )?cold war""" to "The rivalry from 1947 to 1991 between the United States and its allies and the Soviet Union (USSR) and its communist allies, fought with an arms race, spying and proxy wars rather than direct war. Canada joined NATO and NORAD. It ended when the Soviet Union collapsed in 1991.",
        """nato|(?:the )?north atlantic treaty organi[sz]ation""" to "The North Atlantic Treaty Organization, a defence alliance formed in 1949 by Canada, the United States and Western European countries against the Soviet threat: an attack on one is an attack on all. It has 32 members.",
        """globali[sz]ation""" to "The growing connection and interdependence of the world's economies, cultures and peoples through trade, investment, travel, migration and communication technology.",
        """(?:the )?halifax explosion""" to "On December 6, 1917, the French munitions ship Mont-Blanc collided with another ship in Halifax Harbour and exploded, the largest human-made explosion before the atomic bomb. About 2,000 people were killed and 9,000 injured.",
        """(?:the )?holocaust""" to "The genocide by Nazi Germany and its collaborators of about six million Jews, along with millions of others, including Roma and disabled people, during the Second World War. In 1939 Canada turned away the St. Louis, a ship carrying more than 900 Jewish refugees.",
        """(?:the )?cuban missile crisis""" to "In October 1962 the United States found Soviet nuclear missiles in Cuba, and for 13 days the world came close to nuclear war, until the Soviets agreed to remove them. John Diefenbaker hesitated to put Canada's forces on alert.",
        """(?:the )?korean war""" to "From 1950 to 1953 North Korea, backed by China and the Soviet Union, fought South Korea, backed by a United Nations force led by the United States. About 26,000 Canadians served and 516 died. It ended in an armistice, not a peace treaty.",
        """(?:the )?united nations""" to "The international organization founded in 1945, after the Second World War, to keep world peace and security and promote human rights and cooperation among countries. It has 193 member countries; Canada was a founding member.",
        """(?:a )?political part(?:y|ies)""" to "A group of people who share ideas about government and run candidates in elections to win power and carry out their policies, such as the Liberals, Conservatives, NDP, Bloc Québécois and Greens.",
        """(?:the )?battle of the atlantic""" to "The longest campaign of the Second World War, from 1939 to 1945: Allied navies and air forces, with Canada's navy a large part, escorted convoys of merchant ships carrying supplies to Britain against German U-boats.",
        """(?:the )?iron curtain""" to "The political and physical line dividing communist Eastern Europe, under Soviet control, from the democratic West during the Cold War, a phrase Winston Churchill made famous in 1946. It fell in 1989.",
        """(?:the )?vietnam war""" to "From 1955 to 1975 communist North Vietnam and the Viet Cong fought South Vietnam and the United States. Canada stayed out officially, but tens of thousands of Americans avoiding the draft came to Canada. It ended when the North took Saigon in 1975.",
        """question period""" to "The daily 45-minute session in the House of Commons when opposition MPs question the prime minister and cabinet ministers, a key way to hold the government to account.",
        """royal assent""" to "The final step in making a law: the governor general (or a lieutenant governor in a province) approves a bill in the King's name after both houses pass it, and it becomes law.",
        """backbenchers?""" to "An MP who is not a cabinet minister or a party's front-bench critic, so sits behind the front benches and has less say in party policy.",
        """(?:the )?emergencies act""" to "The 1988 law that replaced the War Measures Act. It gives the federal government limited emergency powers that must respect the Charter and be reviewed by Parliament. It was first used in February 2022 against the convoy blockades.",
        """(?:the )?canada pension plan""" to "A public pension passed in 1965 and started in 1966 under Lester Pearson. Workers and employers pay in, and it pays retirement, disability and survivor pensions. Quebec runs its own Quebec Pension Plan.",
        """(?:the )?regina riot""" to "On July 1, 1935, RCMP and city police broke up a rally of On-to-Ottawa trekkers in Regina. A police detective was killed and many were hurt, ending the trek.",
        """(?:the )?relief camps?""" to "Federal camps from 1932 to 1936, under R. B. Bennett and run by the Department of National Defence, where single unemployed men did hard labour building roads and clearing land for food, a bunk and 20 cents a day.",
        """(?:the )?battle of hong kong""" to "In December 1941 nearly 2,000 Canadian soldiers helped defend the British colony of Hong Kong against Japan; it fell on Christmas Day. More than 550 of the Canadians never came home, many dying in brutal prison camps.",
        """(?:the )?liberation of (?:the )?netherlands|(?:the )?liberation of holland""" to "From September 1944 to May 1945 the First Canadian Army drove the Germans out of much of the Netherlands, bringing food to starving Dutch people. More than 7,600 Canadians died. The Dutch still send Ottawa tulips every year in thanks.",
        """(?:the )?chanak (?:crisis|affair)""" to "In 1922 Britain asked the dominions for troops to face Turkey at Chanak. Mackenzie King answered that Canada's Parliament would decide, in effect refusing, a step toward an independent foreign policy.",
        """(?:the )?balfour (?:report|declaration of 1926)""" to "The 1926 Imperial Conference report that declared Britain and the dominions to be autonomous communities within the British Empire, equal in status. It led to the Statute of Westminster in 1931.",
        """(?:the )?king[- ]byng (?:affair|crisis)""" to "In 1926 Governor General Lord Byng refused Prime Minister Mackenzie King's request to dissolve Parliament and asked Arthur Meighen to govern instead. Meighen's government soon fell, and King won the election on the issue, settling that a governor general follows the prime minister's advice.",
        """(?:the )?internment of ukrainian canadians|ukrainian (?:canadian )?internment""" to "From 1914 to 1920, under the War Measures Act, about 8,500 people labelled enemy aliens, most of them Ukrainians from the Austro-Hungarian Empire, were held in 24 camps, and about 80,000 more had to register with police.",
        """(?:the )?continuous journey (?:regulation|rule|law)""" to "A 1908 rule that immigrants had to arrive by a continuous journey from their home country on a through ticket, which was impossible from India, so it kept out South Asians. It led to the Komagata Maru incident in 1914.",
        """(?:the )?1969 white paper|(?:the )?white paper of 1969|(?:the )?white paper on indian policy""" to "The 1969 federal policy, from Pierre Trudeau's government and Indian Affairs minister Jean Chrétien, to abolish the Indian Act, Indian status and treaties and assimilate First Nations. First Nations rejected it in the Red Paper (Citizens Plus), and it was withdrawn in 1971.",
        """(?:the )?(?:94 )?calls to action""" to "The 94 recommendations of the Truth and Reconciliation Commission in 2015 to repair the harm of residential schools, covering child welfare, education, language and culture, health, justice and reconciliation.",
        """aboriginal title""" to "The inherent right of Indigenous peoples to their traditional lands, from occupying them before European sovereignty. Courts recognized it in Calder (1973), defined it in Delgamuukw (1997) and first declared it over a specific area in Tsilhqot'in (2014).",
        """(?:the )?meech lake accord""" to "A 1987 deal between Brian Mulroney and the premiers to recognize Quebec as a distinct society so it would sign the constitution. It failed in June 1990 when Manitoba, where Elijah Harper blocked it, and Newfoundland did not ratify it.",
        """(?:the )?charlottetown accord""" to "A broader 1992 constitutional package (distinct society for Quebec, Senate reform, Indigenous self-government) that Canadians rejected in a national referendum on October 26, 1992, about 54 percent voting No.",
        """(?:the )?parti qu[eé]b[eé]cois""" to "A Quebec provincial party founded in 1968 by René Lévesque to make Quebec a sovereign country. It held the 1980 and 1995 referendums.",
        """(?:the )?bloc qu[eé]b[eé]cois""" to "A federal party founded in 1991 by Lucien Bouchard that runs candidates only in Quebec and supports Quebec sovereignty. It was the Official Opposition from 1993 to 1997.",
        """(?:the )?marshall plan""" to "The American program from 1948 to 1952 that gave about $13 billion in aid to rebuild Western Europe after the Second World War and hold back communism.",
        """norad|(?:the )?north american aerospace defen[cs]e command""" to "The North American Aerospace Defense Command, set up by Canada and the United States in 1958 to watch and defend North American airspace together.",
        """(?:the )?canada health act""" to "The 1984 federal law that sets the rules provinces must meet to get federal health money: health insurance must be publicly administered, comprehensive, universal, portable and accessible, with no extra billing.",
        """free trade""" to "Trade between countries without tariffs, quotas or other barriers. Canada signed free trade with the United States in 1988, then NAFTA in 1994 and CUSMA in 2020.",
        """conservative(?: ideology)?|conservatism""" to "The ideology that values tradition, stability and gradual change over sudden change, with individual responsibility, free markets and limited government. It sits on the right of the political spectrum.",
        """(?:the )?g-?7(?: countries)?""" to "The Group of Seven: Canada, France, Germany, Italy, Japan, the United Kingdom and the United States, plus the European Union, whose leaders meet every year on the world economy and security. Canada joined in 1976.",
        """(?:the )?governor general(?: of canada)?""" to "The King's representative in Canada, appointed on the prime minister's advice for about five years. The governor general gives royal assent to bills, opens Parliament with the Speech from the Throne, swears in the prime minister and cabinet, and is commander-in-chief. The role is mostly ceremonial.",
        """(?:the )?lieutenant governors?""" to "The King's representative in a province, appointed by the governor general on the prime minister's advice. Like the governor general, the role is mostly ceremonial: royal assent, the Throne Speech, swearing in the premier.",
        """(?:the )?house of commons""" to "The elected lower house of Parliament: 343 members of Parliament (MPs), one per riding, elected at least every five years. Most bills start there, and the government must keep its confidence.",
        """(?:the )?senate(?: of canada)?""" to "The appointed upper house of Parliament: 105 senators appointed by the governor general on the prime minister's advice, serving until age 75. It gives bills a sober second thought and can amend or reject them.",
        """(?:the )?parliament of canada|(?:the )?canadian parliament""" to "Canada's federal legislature: the King (through the governor general), the Senate and the House of Commons.",
        """(?:the )?prime minister of canada|(?:the )?canadian prime minister""" to "The head of government, usually the leader of the party with the most seats in the House of Commons. The prime minister picks the cabinet and sets the government's direction.",
        """minority governments?""" to "A government whose party has the most seats but fewer than half of them, not a majority, so it needs support from other parties to pass bills and survive confidence votes.",
        """coalition governments?""" to "A government formed by two or more parties that share cabinet seats to hold a majority together.",
        """first[- ]past[- ]the[- ]post|fptp|single[- ]member plurality""" to "An electoral system where each riding elects one member and the candidate with the most votes wins, even without a majority. Canada uses it federally and in every province.",
        """(?:the )?(?:canadian )?charter of rights(?: and freedoms)?|(?:the )?canadian charter""" to "The Canadian Charter of Rights and Freedoms, part of the Constitution Act, 1982. It protects fundamental freedoms (expression, religion, assembly), democratic, mobility, legal, equality and language rights, and lets courts strike down laws that break them, within reasonable limits (section 1).",
        """(?:the )?notwithstanding clause|section 33(?: of the charter)?""" to "Section 33 of the Charter, which lets Parliament or a provincial legislature override some Charter rights (sections 2 and 7 to 15) by passing a law notwithstanding them, for five years at a time. Quebec, Saskatchewan and Ontario have used it.",
        """(?:the )?constitution of canada|(?:the )?canadian constitution|(?:the )?constitution act,? 1982""" to "Canada's supreme law: the Constitution Act, 1867 (once the BNA Act), which created Confederation and divided federal and provincial powers, and the Constitution Act, 1982, which patriated it from Britain and added the Charter and Aboriginal rights.",
        """(?:the )?statute of westminster(?:,? 1931)?""" to "The 1931 British law that made Canada and the other dominions equal to Britain and independent in making their own laws and foreign policy. Amending the constitution still needed Britain until 1982.",
        """(?:the )?chinese head tax|(?:the )?head tax""" to "A fee charged only to Chinese immigrants entering Canada from 1885: $50, raised to $100 in 1900 and $500 in 1903, meant to keep them out after they had helped build the Canadian Pacific Railway. Canada apologized in 2006.",
        """(?:the )?komagata maru(?: incident)?""" to "In 1914 the ship Komagata Maru brought 376 passengers from British India, mostly Sikhs from Punjab, to Vancouver. Under the continuous journey rule almost all were denied entry and turned away after two months in the harbour; back in India, 19 were killed at Budge Budge. Canada apologized in 2016.",
        """(?:indian )?residential schools?(?: system)?""" to "Boarding schools funded by the federal government and run by churches, from the 1880s to 1996, which about 150,000 First Nations, Métis and Inuit children were forced to attend to assimilate them. Children were cut off from their families, languages and cultures, many were abused, and thousands died. The Truth and Reconciliation Commission called it cultural genocide.",
        """(?:the )?truth and reconciliation commission(?: of canada)?|(?:the )?trc""" to "The Truth and Reconciliation Commission of Canada (2008 to 2015), set up by the residential schools settlement. It gathered the stories of more than 6,500 survivors and issued 94 Calls to Action for reconciliation.",
        """(?:the )?indian act""" to "The federal law, first passed in 1876, that governs First Nations status, reserves and band governments. It was used to control First Nations life: it banned the potlatch from 1884 to 1951 and made residential schools compulsory. It is still in force, amended many times.",
        """(?:the )?on[- ]to[- ]ottawa trek""" to "In 1935 more than 1,000 unemployed men left the federal relief camps in BC and rode freight trains east to protest to Prime Minister R. B. Bennett. The RCMP stopped them in Regina, where the Regina Riot on July 1 left a police officer dead.",
        """(?:the )?persons case""" to "In 1929 the Famous Five (Emily Murphy, Nellie McClung, Irene Parlby, Louise McKinney and Henrietta Muir Edwards) won a ruling from Britain's Privy Council that women are persons under the law, so they could be appointed to the Senate. Canada's Supreme Court had said no in 1928.",
        """(?:the )?conscription crisis(?: of 19(?:17|44))?""" to "Clashes over forcing men into military service (conscription). In 1917 Robert Borden's Military Service Act split the country, with French Canadians in Quebec strongly against it. In 1944 Mackenzie King, who had promised conscription if necessary but not necessarily conscription, sent conscripts overseas, causing a second, smaller crisis.",
        """(?:the )?(?:battle of )?vimy(?: ridge)?""" to "A battle in April 1917, in the First World War, where all four divisions of the Canadian Corps fought together for the first time and took the ridge in northern France from the Germans. About 3,600 Canadians were killed. It became a symbol of Canadian nationhood.",
        """d-?day|d day""" to "June 6, 1944, when Allied forces landed on the beaches of Normandy in German-occupied France in the Second World War. Canadian troops landed at Juno Beach.",
        """(?:the )?quiet revolution""" to "The rapid change in Quebec in the 1960s under Premier Jean Lesage: the province took over education and health care from the Catholic Church, nationalized hydro power (Hydro-Québec) and built a strong French-speaking Quebec identity, feeding the sovereignty movement.",
        """(?:the )?october crisis""" to "In October 1970 the Front de libération du Québec (FLQ) kidnapped British diplomat James Cross and Quebec cabinet minister Pierre Laporte, who was killed. Pierre Trudeau invoked the War Measures Act, its only use in peacetime, sending in troops and arresting about 450 people without charge.",
        """(?:the )?political spectrum""" to "A way of placing political ideas on a line from left to right. The left favours change, equality and more government action; the centre is moderate; the right favours tradition, individual freedom and less government. Radicals and reactionaries sit at the far ends.",
        """left[- ]wing(?: ideology| politics)?|(?:the )?political left""" to "The side of the political spectrum that favours change and social equality, with more government action such as public health care, social programs and regulation of business. In Canada the NDP sits on the left.",
        """multiculturalism""" to "A policy and ideal of welcoming many cultures and letting people keep their heritage while taking part fully in Canadian life. Pierre Trudeau made it official policy in 1971, and the Canadian Multiculturalism Act followed in 1988.",
        """undrip|(?:the )?united nations declaration on the rights of indigenous peoples""" to "The United Nations Declaration on the Rights of Indigenous Peoples, adopted in 2007. It sets out Indigenous peoples' rights to self-determination, land, culture and free, prior and informed consent. BC made it law in 2019 and Canada in 2021.",
    ).map { Triple(Regex("^(?:" + it.first + ")$"), it.second, it.first) }

    private fun out(body: String) = Answer.Text(heading = null, body = body, source = "Nimble social studies")

    fun answer(q: String): Answer? {
        for ((re, body) in facts) if (re.containsMatchIn(q)) return out(body)
        return Terms.answer(q.replace(Regex(" in canada$"), ""), terms, emptyList())?.let { out(it) }
    }
}
